sp_widget.css:
.chat-container {
  width: 100%;
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  height: 80vh;
  border: 1px solid #ccc;
  border-radius: 8px;
  overflow: hidden;
  background: #f5f5f5;
}

.chat-messages {
  flex: 1;
  padding: 16px;
  overflow-y: auto;
}

.chat-message {
  margin-bottom: 10px;
  display: flex;
  align-items: flex-start;
}

.user-message {
  align-self: flex-end;
  background: #0084ff;
  color: white;
  border-radius: 16px;
  margin-left: auto;
  padding: 8px 12px;
  max-width: 60%;
}

.assistant-message {
  background: #e4e6eb;
  border-radius: 16px;
  padding: 8px 12px;
  max-width: 60%;
}

.message-content {
  font-size: 14px;
  line-height: 1.4;
}

.chat-input-form {
  display: flex;
  border-top: 1px solid #ccc;
  background: white;
}

.chat-input {
  flex: 1;
  padding: 10px 12px;
  border: none;
  outline: none;
  font-size: 16px;
}

.send-button {
  background: #0084ff;
  border: none;
  color: white;
  padding: 10px 16px;
  cursor: pointer;
  transition: background 0.3s;
}

.send-button:hover {
  background: #006bbf;
}
